1020	Status CollectionImpl::validate(const std::string &column,
1021	                                const FieldSchema::Ptr &schema,
1022	                                const std::string &expression,
1023	                                const std::string &rename, ColumnOp op) {
1024	  auto check_data_type = [&](const FieldSchema *field) -> Status {
1025	    if (field->data_type() < DataType::INT32 ||
1026	        field->data_type() > DataType::DOUBLE) {
1027	      return Status::InvalidArgument(
1028	          "Only support basic numeric data type [int32, int64, uint32, uint64, "
1029	          "float, double]: ",
1030	          field->to_string());
1031	    }
1032	    return Status::OK();
1033	  };
1034	
1035	  switch (op) {
1036	    case ColumnOp::ADD: {
1037	      if (schema == nullptr) {
1038	        return Status::InvalidArgument("Column schema is null");
1039	      }
1040	
1041	      if (schema->name().empty()) {
1042	        return Status::InvalidArgument("Column name is empty");
1043	      }
1044	      if (schema_->has_field(schema->name())) {
1045	        return Status::InvalidArgument("column already exists: ",
1046	                                       schema->name());
1047	      }
1048	
1049	      auto s = schema->validate();
1050	      CHECK_RETURN_STATUS(s);
1051	
1052	      s = check_data_type(schema.get());
1053	      CHECK_RETURN_STATUS(s);
1054	
1055	      if (expression.empty() && !schema->nullable()) {
1056	        return Status::InvalidArgument(
1057	            "Add column is not supported for non-nullable column: ",
1058	            schema->name());
1059	      }
1060	
1061	      break;
1062	    }
1063	    case ColumnOp::ALTER: {
1064	      if (column.empty()) {
1065	        return Status::InvalidArgument("column name is empty");
1066	      }
1067	
1068	      if (!schema_->has_field(column)) {
1069	        return Status::InvalidArgument("column ", column, " not found");
1070	      }
1071	
1072	      if (!rename.empty() && schema) {
1073	        return Status::InvalidArgument(
1074	            "cannot specify both rename and new column schema");
1075	      }
1076	
1077	      auto *old_field_schema = schema_->get_field(column);
1078	      auto s = check_data_type(old_field_schema);
1079	      CHECK_RETURN_STATUS(s);
1080	
1081	      if (!rename.empty()) {
1082	        // rename case
1083	        if (schema_->has_field(rename)) {
1084	          return Status::InvalidArgument("new column name ", rename,
1085	                                         " already exists");
1086	        }
1087	      } else {
1088	        // schema change case
1089	        if (!schema) {
1090	          return Status::InvalidArgument("New column schema is null");
1091	        }
1092	
1093	        s = schema->validate();
1094	        CHECK_RETURN_STATUS(s);
1095	
1096	        if (schema->name().empty()) {
1097	          return Status::InvalidArgument("new column schema name is empty");
1098	        }
1099	
1100	        if (!schema->nullable() && old_field_schema->nullable()) {
1101	          return Status::InvalidArgument(
1102	              "new column schema is not nullable, but old column schema is "
1103	              "nullable");
1104	        }
1105	
1106	        if (*old_field_schema == *schema) {
1107	          // equal schema
1108	          return Status::OK();
1109	        }
1110	
1111	        s = check_data_type(schema.get());
1112	        CHECK_RETURN_STATUS(s);
1113	      }
1114	
1115	      break;
1116	    }
1117	    case ColumnOp::DROP: {
1118	      if (!schema_->has_field(column)) {
1119	        return Status::InvalidArgument("Column not exists: ", column);
1120	      }
1121	
1122	      auto *old_field_schema = schema_->get_field(column);
1123	      auto s = check_data_type(old_field_schema);
1124	      CHECK_RETURN_STATUS(s);
1125	      break;
1126	    }
1127	    default:
1128	      break;
1129	  }
1130	
1131	  return Status::OK();
1132	}
1133	
1134	Status CollectionImpl::AddColumn(const FieldSchema::Ptr &column_schema,
1135	                                 const std::string &expression,
1136	                                 const AddColumnOptions &options) {
1137	  CHECK_COLLECTION_READONLY_RETURN_STATUS;
1138	
1139	  std::lock_guard lock(schema_handle_mtx_);
1140	
1141	  CHECK_DESTROY_RETURN_STATUS(destroyed_, false);
1142	
1143	  // validate
1144	  auto s = validate("", column_schema, expression, "", ColumnOp::ADD);
1145	  CHECK_RETURN_STATUS(s);
1146	
1147	  // forbidden writing until index is ready
1148	  std::lock_guard write_lock(write_mtx_);
1149	
1150	  auto new_schema = std::make_shared<CollectionSchema>(*schema_);
1151	  s = new_schema->add_field(column_schema);
1152	  CHECK_RETURN_STATUS(s);
1153	
1154	  if (writing_segment_->doc_count() > 0) {
1155	    s = switch_to_new_segment_for_writing();
1156	    CHECK_RETURN_STATUS(s);
1157	  }
1158	
1159	  Version new_version = version_manager_->get_current_version();
1160	
1161	  // add column on segment manager
1162	  s = segment_manager_->add_column(column_schema, expression,
1163	                                   options.concurrency_);
1164	  CHECK_RETURN_STATUS(s);
1165	
1166	  // reset writing segment with new schema
