1605	Result<DocPtrList> CollectionImpl::Query(const SearchQuery &query) const {
1606	  std::shared_lock lock(schema_handle_mtx_);
1607	
1608	  CHECK_DESTROY_RETURN_STATUS_EXPECTED(destroyed_, false);
1609	
1610	  // When field_name_ is set, use get_field to retrieve the schema uniformly.
1611	  // validate checks that the field type matches the query type
1612	  // (FTS query requires an FTS field, vector query requires a vector field).
1613	  const auto &field_name = query.target_.field_name_;
1614	  const FieldSchema *field_schema =
1615	      field_name.empty() ? nullptr : schema_->get_field(field_name);
1616	  bool need_sanitize = false;
1617	  auto s = query.validate(field_schema, &need_sanitize);
1618	  CHECK_RETURN_STATUS_EXPECTED(s);
1619	
1620	  auto segments = get_all_segments();
1621	  if (segments.empty()) {
1622	    return DocPtrList();
1623	  }
1624	
1625	  if (!need_sanitize) {
1626	    return sql_engine_->execute(schema_, query, segments);
1627	  }
1628	
1629	  // Sparse needs sanitization: make a mutable copy and sort indices in place.
1630	  SearchQuery sanitized_query = query;
1631	  auto ss = sanitize_sparse_vector(sanitized_query.target_, field_schema);
1632	  CHECK_RETURN_STATUS_EXPECTED(ss);
1633	  return sql_engine_->execute(schema_, std::move(sanitized_query), segments);
1634	}
1635	
1636	Result<DocPtrList> CollectionImpl::Query(const MultiQuery &query) const {
1637	  std::shared_lock lock(schema_handle_mtx_);
1638	
1639	  CHECK_DESTROY_RETURN_STATUS_EXPECTED(destroyed_, false);
1640	
1641	  if (query.queries.size() < 2) {
1642	    return tl::make_unexpected(Status::InvalidArgument(
1643	        "Invalid query: MultiQuery requires at least 2 sub-queries, got ",
1644	        query.queries.size()));
1645	  }
1646	
1647	  if (auto s = validate_topk_and_output_fields(query.topk, query.output_fields);
1648	      !s.ok()) {
1649	    return tl::make_unexpected(s);
1650	  }
1651	
1652	  auto segments = get_all_segments();
1653	  if (segments.empty()) {
1654	    return DocPtrList();
1655	  }
1656	
1657	  // Convert each SubQuery to a SearchQuery and validate.
1658	  std::vector<SearchQuery> pending_queries;
1659	  std::vector<FieldSchema::Ptr> field_schemas;
1660	  pending_queries.reserve(query.queries.size());
1661	  field_schemas.reserve(query.queries.size());
1662	
1663	  for (const auto &sub : query.queries) {
1664	    const auto &target = sub.target_;
1665	    auto field_ptr = schema_->get_field_ptr(target.field_name_);
1666	    if (!field_ptr) {
1667	      return tl::make_unexpected(Status::InvalidArgument(
1668	          "Invalid query: field ", target.field_name_, " not found"));
1669	    }
1670	    auto *field_schema = field_ptr.get();
1671	
1672	    bool need_sanitize = false;
1673	    auto s = target.validate(field_schema, &need_sanitize);
1674	    CHECK_RETURN_STATUS_EXPECTED(s);
1675	
1676	    SearchQuery sq;
1677	    sq.target_ = target;
1678	    sq.topk_ = sub.num_candidates_;
1679	    sq.filter_ = query.filter;
1680	    sq.include_vector_ = query.include_vector;
1681	    sq.include_doc_id_ = query.include_doc_id_;
1682	    sq.output_fields_ = query.output_fields;
1683	
1684	    if (need_sanitize) {
1685	      auto ss = sanitize_sparse_vector(sq.target_, field_schema);
1686	      CHECK_RETURN_STATUS_EXPECTED(ss);
1687	    }
1688	    pending_queries.push_back(std::move(sq));
1689	    field_schemas.push_back(std::move(field_ptr));
1690	  }
1691	
1692	  auto execute_query = [&](SearchQuery &pending) -> Result<DocPtrList> {
1693	    auto engine = sqlengine::SQLEngine::create(std::make_shared<Profiler>());
1694	    return engine->execute(schema_, std::move(pending), segments);
1695	  };
1696	
1697	  std::vector<Result<DocPtrList>> results(pending_queries.size());
1698	
1699	  // Single-segment queries have no segment-level fanout; multi-segment queries
1700	  // already use the query pool per sub-query.
1701	  if (segments.size() == 1) {
1702	    auto group = GlobalResource::Instance().query_thread_pool()->make_group();
1703	    for (size_t i = 0; i < pending_queries.size(); ++i) {
1704	      group->execute(
1705	          [&, i]() { results[i] = execute_query(pending_queries[i]); });
1706	    }
1707	    group->wait_finish();
1708	  } else {
1709	    for (size_t i = 0; i < pending_queries.size(); ++i) {
1710	      results[i] = execute_query(pending_queries[i]);
1711	    }
1712	  }
1713	
1714	  std::vector<DocPtrList> query_results;
1715	  query_results.reserve(pending_queries.size());
1716	  for (size_t i = 0; i < pending_queries.size(); ++i) {
1717	    if (!results[i]) {
1718	      return tl::make_unexpected(results[i].error());
1719	    }
1720	    query_results.push_back(std::move(results[i].value()));
1721	  }
1722	
1723	  // Dispatch rerank — schema info injected via field_schemas
1724	  return reranker::rerank(query.rerank, query_results, field_schemas,
1725	                          query.topk);
1726	}
1727	
1728	Result<GroupResults> CollectionImpl::GroupByQuery(
1729	    const GroupByVectorQuery &query) const {
1730	  std::shared_lock lock(schema_handle_mtx_);
1731	
1732	  CHECK_DESTROY_RETURN_STATUS_EXPECTED(destroyed_, false);
1733	
1734	  auto segments = get_all_segments();
1735	  if (segments.empty()) {
1736	    return GroupResults();
1737	  }
1738	
1739	  // Determine vector data source (zero-copy for dense, copy+sort for sparse)
1740	  const FieldSchema *field_schema =
1741	      schema_->get_field(query.target_.field_name_);
1742	  bool need_sanitize = false;
1743	  auto s = query.target_.validate(field_schema, &need_sanitize);
1744	  CHECK_RETURN_STATUS_EXPECTED(s);
1745	
1746	  if (!need_sanitize) {
1747	    return sql_engine_->execute_group_by(schema_, query, segments);
1748	  }
1749	
1750	  // Sparse needs sanitization: make a mutable copy and sort indices in place.
1751	  GroupByVectorQuery sanitized_query = query;
1752	  auto ss = sanitize_sparse_vector(sanitized_query.target_, field_schema);
1753	  CHECK_RETURN_STATUS_EXPECTED(ss);
1754	  return sql_engine_->execute_group_by(schema_, sanitized_query, segments);
1755	}
1756	
1757	Result<DocPtrMap> CollectionImpl::Fetch(
1758	    const std::vector<std::string> &pks,
1759	    const std::optional<std::vector<std::string>> &output_fields,
1760	    bool include_vector) const {
1761	  std::shared_lock lock(schema_handle_mtx_);
1762	
1763	  CHECK_DESTROY_RETURN_STATUS_EXPECTED(destroyed_, false);
1764	
1765	  auto segments = get_all_segments();
1766	
1767	  DocPtrMap results;
1768	
1769	  for (auto &pk : pks) {
1770	    uint64_t doc_id;
1771	    bool has = id_map_->has(pk, &doc_id);
1772	    if (!has) {
1773	      results.insert({pk, nullptr});
1774	      continue;
1775	    }
1776	    if (delete_store_->is_deleted(doc_id)) {
1777	      results.insert({pk, nullptr});
1778	      continue;
1779	    }
1780	    auto segment = local_segment_by_doc_id(doc_id, segments);
1781	    if (!segment) {
1782	      LOG_WARN("doc_id: %zu segment not found", (size_t)doc_id);
1783	      results.insert({pk, nullptr});
1784	      continue;
1785	    }
1786	    results.insert({pk, segment->Fetch(doc_id, output_fields, include_vector)});
1787	  }
1788	
1789	  return results;
1790	}
1791	
1792	Result<std::string> CollectionImpl::DebugGetHnswStorageMode(
1793	    const std::string &column_name) const {
1794	  std::shared_lock lock(schema_handle_mtx_);
1795	
1796	  CHECK_DESTROY_RETURN_STATUS_EXPECTED(destroyed_, false);
1797	
1798	  // Try all segments (including the writing one). The first segment that has
1799	  // a fully-built HNSW index wins; if only a building segment exists we still
1800	  // surface its current storage mode so that tests can observe the entity
1801	  // type right after Open().
1802	  auto segments = get_all_segments();
1803	
1804	  for (const auto &segment : segments) {
1805	    if (!segment) {
1806	      continue;
1807	    }
1808	    auto indexers = segment->get_vector_indexer(column_name);
1809	    for (const auto &indexer : indexers) {
1810	      if (!indexer) {
1811	        continue;
1812	      }
1813	      auto index = indexer->debug_get_index();
1814	      if (!index) {
1815	        continue;
1816	      }
1817	      auto *hnsw_index = dynamic_cast<core_interface::HNSWIndex *>(index.get());
1818	      if (!hnsw_index) {
1819	        return tl::make_unexpected(Status::InvalidArgument(
1820	            "Column '", column_name,
1821	            "' does not have an HNSW index (or index is sparse)"));
1822	      }
1823	      auto mode = hnsw_index->storage_mode();
1824	      if (mode.empty()) {
1825	        // streamer not initialized yet; skip and look at other segments
1826	        continue;
1827	      }
1828	      return mode;
1829	    }
1830	  }
1831	
1832	  return tl::make_unexpected(
1833	      Status::NotFound("No HNSW index found for column '", column_name, "'"));
1834	}
1835	
1836	Status CollectionImpl::recovery() {
1837	  if (!FileHelper::DirectoryExists(path_.c_str())) {
1838	    return Status::InvalidArgument("collection path{", path_, "} not exist.");
1839	  }
1840	
1841	  // get lock file
1842	  auto s = acquire_file_lock(false);
1843	  CHECK_RETURN_STATUS(s);
1844	
1845	  // recovery version first
1846	  auto version_manager = VersionManager::Recovery(path_);
1847	  if (!version_manager.has_value()) {
1848	    return version_manager.error();
1849	  }
1850	
1851	  version_manager_ = version_manager.value();
1852	  const auto v = version_manager_->get_current_version();
1853	  schema_ = std::make_shared<CollectionSchema>(v.schema());
1854	  options_.enable_mmap_ = v.enable_mmap();
1855	  s = recover_idmap_and_delete_store();
1856	  CHECK_RETURN_STATUS(s);
1857	
1858	  // recover persist segments
1859	  segment_manager_ = std::make_shared<SegmentManager>();
1860	
1861	  auto segment_metas = v.persisted_segment_metas();
1862	
1863	  SegmentOptions seg_options;
1864	  seg_options.read_only_ = true;
1865	  seg_options.enable_mmap_ = options_.enable_mmap_;
1866	  for (size_t i = 0; i < segment_metas.size(); ++i) {
1867	    auto segment = Segment::Open(path_, *schema_, *segment_metas[i], id_map_,
1868	                                 delete_store_, version_manager_, seg_options);
1869	    if (!segment) {
1870	      return segment.error();
1871	    }
1872	
1873	    segment_manager_->add_segment(segment.value());
1874	  }
1875	
1876	  seg_options.read_only_ = options_.read_only_;
1877	  seg_options.max_buffer_size_ = options_.max_buffer_size_;
1878	
1879	  // recover writing segment
1880	  auto writing_segment =
1881	      Segment::Open(path_, *schema_, *v.writing_segment_meta(), id_map_,
1882	                    delete_store_, version_manager_, seg_options);
1883	  if (!writing_segment) {
1884	    return writing_segment.error();
1885	  }
1886	
1887	  writing_segment_ = writing_segment.value();
1888	  segment_id_allocator_.store(v.next_segment_id());
1889	
1890	  // recover id map & delete store
1891	  return Status::OK();
1892	}
1893	
1894	Status CollectionImpl::recover_idmap_and_delete_store() {
1895	  const auto v = version_manager_->get_current_version();
1896	
1897	  // idmap
1898	  std::string idmap_path =
1899	      FileHelper::MakeFilePath(path_, FileID::ID_FILE, v.id_map_path_suffix());
1900	  id_map_ = IDMap::CreateAndOpen(schema_->name(), idmap_path, false,
1901	                                 options_.read_only_);
1902	  if (!id_map_) {
1903	    return Status::InternalError("recovery idmap failed, path: ", idmap_path);
1904	  }
1905	
1906	  // delete store
1907	  std::string delete_store_path = FileHelper::MakeFilePath(
1908	      path_, FileID::DELETE_FILE, v.delete_snapshot_path_suffix());
1909	  delete_store_ =
1910	      DeleteStore::CreateAndLoad(schema_->name(), delete_store_path);
1911	  if (!delete_store_) {
1912	    return Status::InternalError("recovery delete store failed, path: ",
1913	                                 delete_store_path);
1914	  }
1915	
1916	  return Status::OK();
1917	}
1918	
1919	Status CollectionImpl::create() {
1920	  // check path
1921	  if (path_.empty()) {
1922	    return Status::InvalidArgument("path validate failed: path is empty");
1923	  }
1924	  if (!FileHelper::PathSimpleValidation(path_)) {
1925	    return Status::InvalidArgument("path validate failed: path[", path_,
1926	                                   "] is not a valid path");
1927	  }
1928	  if (ailego::FileHelper::IsExist(path_.c_str())) {
1929	    return Status::InvalidArgument("path validate failed: path[", path_,
1930	                                   "] exists, create expects a path that does "
1931	                                   "not exist");
1932	  }
1933	
1934	  // check schema
1935	  auto s = schema_->validate();
1936	  CHECK_RETURN_STATUS(s);
1937	
1938	  if (!ailego::FileHelper::MakePath(path_.c_str())) {
1939	    return Status::InvalidArgument(
1940	        "create collection path failed: ", path_,
1941	        ", error: ", ailego::FileHelper::GetLastErrorString());
1942	  }
1943	
1944	  // init lock file
1945	  s = acquire_file_lock(true);
1946	  CHECK_RETURN_STATUS(s);
1947	
1948	  // init idmap & delete store
1949	  s = create_idmap_and_delete_store();
1950	  CHECK_RETURN_STATUS(s);
1951	
1952	  // init version manager
1953	  s = init_version_manager();
1954	  CHECK_RETURN_STATUS(s);
1955	
1956	  // create segment
1957	  s = init_writing_segment();
1958	  CHECK_RETURN_STATUS(s);
1959	
1960	  // init version
1961	  Version version;
1962	  version.set_schema(*schema_);
1963	  version.set_enable_mmap(options_.enable_mmap_);
1964	  version.reset_writing_segment_meta(writing_segment_->meta());
1965	  version.set_id_map_path_suffix(0);
1966	  version.set_delete_snapshot_path_suffix(0);
1967	  version.set_next_segment_id(1);
1968	
1969	  version_manager_->apply(version);
1970	  s = version_manager_->flush();
1971	  CHECK_RETURN_STATUS(s);
1972	
1973	  segment_id_allocator_.store(1);
1974	  segment_manager_ = std::make_unique<SegmentManager>();
1975	
1976	  return Status::OK();
1977	}
1978	
1979	Status CollectionImpl::create_idmap_and_delete_store() {
1980	  // idmap
1981	  std::string idmap_path = FileHelper::MakeFilePath(path_, FileID::ID_FILE, 0);
1982	  id_map_ = IDMap::CreateAndOpen(schema_->name(), idmap_path, true,
1983	                                 options_.read_only_);
1984	  if (!id_map_) {
1985	    return Status::InternalError("create id map failed, path: ", idmap_path);
1986	  }
1987	
1988	  std::string delete_store_path =
1989	      FileHelper::MakeFilePath(path_, FileID::DELETE_FILE, 0);
1990	  delete_store_ = std::make_shared<DeleteStore>(schema_->name());
1991	  // when first create collection, delete store will flush a empty snapshot
1992	  delete_store_->flush(delete_store_path);
1993	
1994	  return Status::OK();
1995	}
1996	
1997	Status CollectionImpl::init_version_manager() {
1998	  // use empty version to init version manager
1999	  auto version_manager = VersionManager::Create(path_, Version{});
2000	  if (!version_manager.has_value()) {
2001	    return version_manager.error();
2002	  }
2003	
2004	  version_manager_ = version_manager.value();
2005	  return Status::OK();
2006	}
2007	
2008	Status CollectionImpl::init_writing_segment() {
2009	  SegmentOptions options;
2010	  options.enable_mmap_ = options_.enable_mmap_;
2011	  options.max_buffer_size_ = options_.max_buffer_size_;
2012	  options.read_only_ = options_.read_only_;
2013	
2014	  auto writing_segment = Segment::CreateAndOpen(
2015	      path_, *schema_, 0, 0, id_map_, delete_store_, version_manager_, options);
2016	
2017	  if (!writing_segment) {
2018	    return writing_segment.error();
2019	  }
2020	
2021	  writing_segment_ = writing_segment.value();
2022	
2023	  return Status::OK();
2024	}
2025	
2026	Status CollectionImpl::acquire_file_lock(bool create) {
2027	  std::string lock_file_path = ailego::FileHelper::PathJoin(path_, "LOCK");
2028	
2029	  if (create) {
2030	    if (!lock_file_.create(lock_file_path.c_str(), 0)) {
2031	      return Status::InternalError("Can't create lock file: ", lock_file_path);
2032	    }
2033	  } else {
2034	    if (!lock_file_.open(lock_file_path.c_str(), options_.read_only_)) {
2035	      return Status::InternalError("Can't open lock file: ", lock_file_path);
2036	    }
2037	  }
2038	
2039	  if (options_.read_only_) {
2040	    if (!ailego::FileLock::TryLockShared(lock_file_.native_handle())) {
2041	      return Status::InternalError("Can't lock read-only collection: ",
2042	                                   lock_file_path);
2043	    }
2044	  } else {
2045	    if (!ailego::FileLock::TryLock(lock_file_.native_handle())) {
2046	      return Status::InternalError("Can't lock read-write collection: ",
2047	                                   lock_file_path);
2048	    }
2049	  }
2050	
2051	  return Status::OK();
2052	}
2053	
2054	Segment::Ptr CollectionImpl::local_segment_by_doc_id(
2055	    uint64_t doc_id, const std::vector<Segment::Ptr> &segments) const {
2056	  size_t left = 0;
2057	  size_t right = segments.size();
2058	
2059	  while (left < right) {
2060	    size_t mid = left + (right - left) / 2;
2061	    uint64_t min_id = segments[mid]->meta()->min_doc_id();
2062	    uint64_t max_id = segments[mid]->meta()->max_doc_id();
2063	
2064	    if (doc_id < min_id) {
2065	      right = mid;
2066	    } else if (doc_id > max_id) {
2067	      left = mid + 1;
2068	    } else {
2069	      return segments[mid];
2070	    }
2071	  }
2072	
2073	  return nullptr;
2074	}
2075	
2076	std::vector<Segment::Ptr> CollectionImpl::get_all_segments() const {
2077	  std::vector<Segment::Ptr> segments = get_all_persist_segments();
2078	  if (writing_segment_->doc_count() > 0) {
2079	    segments.push_back(writing_segment_);
2080	  }
2081	  return segments;
2082	}
2083	
2084	std::vector<Segment::Ptr> CollectionImpl::get_all_persist_segments() const {
2085	  return segment_manager_->get_segments();
2086	}
2087	
2088	}  // namespace zvec
