70	int LocalWalFile::open(const WalOptions &wal_option) {
71	  CHECK_STATUS(opened_, false);
72	  if (wal_option.create_new) {
73	    if (FileHelper::FileExists(wal_path_)) {
74	      WLOG_ERROR("Wal open error. file already exist create_new[%d]",
75	                 wal_option.create_new);
