95	                 wal_option.create_new);
96	      return -1;
97	    }
98	
99	    if (!file_.open(wal_path_.c_str(), false)) {
100	      WLOG_ERROR("Wal open error. create_new[%d]", wal_option.create_new);
101	      return -1;
102	    }
103	
104	    // open default for write
105	    file_.seek(0, ailego::File::Origin::End);
106	  }
